use std::fs

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut keys: Vec<int> = []
    let mut left: Vec<int> = []
    let mut right: Vec<int> = []
    let mut root = -1
    let mut out: Vec<string> = []
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().map(|s| s.to_string()).collect()
        if parts.len() == 0 {
            continue
        }
        let cmd = parts[0]
        let mut x = 0
        if parts.len() > 1 {
            x = parts[1].parse::<int>().unwrap_or(0)
        }
        if cmd == "insert" {
            if root == -1 {
                keys.push(x)
                left.push(-1)
                right.push(-1)
                root = keys.len() as int - 1
                out.push("ok")
            } else {
                let mut cur = root
                let mut done = false
                while !done {
                    if keys[cur] == x {
                        out.push("dup")
                        done = true
                    } else if x < keys[cur] {
                        if left[cur] == -1 {
                            keys.push(x)
                            left.push(-1)
                            right.push(-1)
                            left[cur] = keys.len() as int - 1
                            out.push("ok")
                            done = true
                        } else {
                            cur = left[cur]
                        }
                    } else {
                        if right[cur] == -1 {
                            keys.push(x)
                            left.push(-1)
                            right.push(-1)
                            right[cur] = keys.len() as int - 1
                            out.push("ok")
                            done = true
                        } else {
                            cur = right[cur]
                        }
                    }
                }
            }
        } else if cmd == "contains" {
            let mut cur = root
            let mut found = false
            while cur != -1 && !found {
                if keys[cur] == x {
                    found = true
                } else if x < keys[cur] {
                    cur = left[cur]
                } else {
                    cur = right[cur]
                }
            }
            if found { out.push("yes") } else { out.push("no") }
        } else if cmd == "delete" {
            let mut cur = root
            let mut parent = -1
            let mut found = false
            while cur != -1 && !found {
                if keys[cur] == x {
                    found = true
                } else {
                    parent = cur
                    if x < keys[cur] { cur = left[cur] } else { cur = right[cur] }
                }
            }
            if !found {
                out.push("missing")
            } else {
                if left[cur] != -1 && right[cur] != -1 {
                    let mut sp = cur
                    let mut s = right[cur]
                    while left[s] != -1 {
                        sp = s
                        s = left[s]
                    }
                    keys[cur] = keys[s]
                    if sp == cur {
                        right[sp] = right[s]
                    } else {
                        left[sp] = right[s]
                    }
                } else {
                    let child = if left[cur] != -1 { left[cur] } else { right[cur] }
                    if parent == -1 {
                        root = child
                    } else if left[parent] == cur {
                        left[parent] = child
                    } else {
                        right[parent] = child
                    }
                }
                out.push("ok")
            }
        } else if cmd == "inorder" {
            let mut stack: Vec<int> = []
            let mut res: Vec<string> = []
            let mut cur = root
            while cur != -1 || stack.len() > 0 {
                while cur != -1 {
                    stack.push(cur)
                    cur = left[cur]
                }
                let n = stack.pop().unwrap_or(0)
                res.push("${keys[n]}")
                cur = right[n]
            }
            if res.len() == 0 { out.push("<empty>") } else { out.push(res.join(" ")) }
        } else if cmd == "height" {
            let mut best = 0
            if root != -1 {
                let mut ns: Vec<int> = [root]
                let mut ds: Vec<int> = [1]
                while ns.len() > 0 {
                    let n = ns.pop().unwrap_or(0)
                    let d = ds.pop().unwrap_or(0)
                    if d > best { best = d }
                    if left[n] != -1 {
                        ns.push(left[n])
                        ds.push(d + 1)
                    }
                    if right[n] != -1 {
                        ns.push(right[n])
                        ds.push(d + 1)
                    }
                }
            }
            out.push("${best}")
        } else if cmd == "min" || cmd == "max" {
            if root == -1 {
                out.push("empty")
            } else {
                let mut cur = root
                if cmd == "min" {
                    while left[cur] != -1 { cur = left[cur] }
                } else {
                    while right[cur] != -1 { cur = right[cur] }
                }
                out.push("${keys[cur]}")
            }
        }
    }
    for o in out { println(o) }
}

